import { spawn } from 'node:child_process';
import { writeFile } from 'node:fs/promises';

const URL = process.argv[2] || 'file:///home/runner/work/OhMyGithub/OhMyGithub/index.html';
const PORT = 9333;
const CHROME = process.env.CHROME || 'chromium';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const chrome = spawn(CHROME, [
  '--headless=new',
  '--no-sandbox',
  '--disable-dev-shm-usage',
  '--disable-gpu',
  '--hide-scrollbars',
  `--remote-debugging-port=${PORT}`,
  '--window-size=900,760',
  URL
], { stdio: ['ignore', 'ignore', 'pipe'] });

let chromeErr = '';
chrome.stderr.on('data', (d) => { chromeErr += d; });

async function getPage() {
  for (let i = 0; i < 100; i++) {
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json/list`);
      const targets = await res.json();
      const page = targets.find((t) => t.type === 'page');
      if (page) return page;
    } catch {}
    await sleep(100);
  }
  throw new Error('Chromium page target not found\n' + chromeErr);
}

const page = await getPage();
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true });
  ws.addEventListener('error', reject, { once: true });
});

let nextId = 1;
const pending = new Map();
ws.addEventListener('message', (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(JSON.stringify(msg.error)));
    else resolve(msg.result);
  }
});

function send(method, params = {}) {
  const id = nextId++;
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
}

async function evaluate(expression) {
  const result = await send('Runtime.evaluate', {
    expression,
    returnByValue: true,
    awaitPromise: true
  });
  if (result.exceptionDetails) {
    throw new Error(result.exceptionDetails.text + ' ' + (result.exceptionDetails.exception?.description || ''));
  }
  return result.result.value;
}

async function key(type, keyName, code, vk) {
  await send('Input.dispatchKeyEvent', {
    type,
    key: keyName,
    code,
    windowsVirtualKeyCode: vk,
    nativeVirtualKeyCode: vk
  });
}

async function press(keyName, code, vk) {
  await key('rawKeyDown', keyName, code, vk);
  await key('keyUp', keyName, code, vk);
}

async function shot(name) {
  const { data } = await send('Page.captureScreenshot', { format: 'png' });
  await writeFile(name, Buffer.from(data, 'base64'));
}

const log = (...a) => console.log(...a);

try {
  await send('Page.enable');
  await send('Runtime.enable');

  // Wait for the game to boot.
  for (let i = 0; i < 50; i++) {
    const ready = await evaluate('typeof window.__pong === "object"');
    if (ready) break;
    await sleep(100);
  }

  const initial = await evaluate('window.__pong.snapshot()');
  log('initial:', JSON.stringify(initial));
  if (initial.mode !== 'ready' || initial.score.player !== 0 || initial.score.cpu !== 0) {
    throw new Error('unexpected initial state');
  }
  await shot('/tmp/opencode/pong-ready.png');

  // Space should serve.
  await press(' ', 'Space', 32);
  await sleep(250);
  const serving = await evaluate('window.__pong.snapshot()');
  log('after space:', JSON.stringify(serving));
  if (serving.mode !== 'playing') throw new Error('space did not start play');
  if (serving.ball.vx === 0 && serving.ball.vy === 0) throw new Error('ball is not moving');

  // Ball should travel.
  const a = await evaluate('window.__pong.snapshot().ball');
  await sleep(400);
  const b = await evaluate('window.__pong.snapshot().ball');
  log('ball t0:', JSON.stringify(a));
  log('ball t1:', JSON.stringify(b));
  if (Math.hypot(b.x - a.x, b.y - a.y) < 20) throw new Error('ball did not travel');

  // ArrowUp should move the player paddle up.
  const playerBefore = (await evaluate('window.__pong.snapshot()')).player.y;
  await key('rawKeyDown', 'ArrowUp', 'ArrowUp', 38);
  await sleep(300);
  await key('keyUp', 'ArrowUp', 'ArrowUp', 38);
  const playerAfter = (await evaluate('window.__pong.snapshot()')).player.y;
  log('player y:', playerBefore.toFixed(1), '->', playerAfter.toFixed(1));
  if (!(playerAfter < playerBefore - 20)) throw new Error('ArrowUp did not move paddle');

  // ArrowDown should move it back down.
  await key('rawKeyDown', 'ArrowDown', 'ArrowDown', 40);
  await sleep(300);
  await key('keyUp', 'ArrowDown', 'ArrowDown', 40);
  const playerDown = (await evaluate('window.__pong.snapshot()')).player.y;
  log('player y after down:', playerDown.toFixed(1));
  if (!(playerDown > playerAfter + 20)) throw new Error('ArrowDown did not move paddle');

  // Pause and resume.
  await press('p', 'KeyP', 80);
  await sleep(120);
  const paused = await evaluate('window.__pong.snapshot()');
  log('paused mode:', paused.mode);
  if (paused.mode !== 'paused') throw new Error('P did not pause');
  await shot('/tmp/opencode/pong-paused.png');
  await press('p', 'KeyP', 80);
  await sleep(120);
  const resumed = await evaluate('window.__pong.snapshot()');
  log('resumed mode:', resumed.mode);
  if (resumed.mode !== 'playing') throw new Error('P did not resume');

  // Let a few seconds of play run; CPU should score against an idle player.
  await sleep(5000);
  const later = await evaluate('window.__pong.snapshot()');
  log('after 5s of play:', JSON.stringify(later));
  if (later.score.player + later.score.cpu < 1) {
    throw new Error('no point was scored in 5s of play');
  }
  await shot('/tmp/opencode/pong-playing.png');

  log('VERIFY OK');
} finally {
  try { ws.close(); } catch {}
  chrome.kill('SIGKILL');
}

